const dictionaries: Record<Lang, Record<Key, string>> = { fr, en };

function detectLang(): Lang {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored === "fr" || stored === "en") return stored;
  } catch { /* stockage indisponible : on retombe sur le français */ }
  // IMPORTANT : français par défaut. La langue de la webview (souvent en-US) ne reflète pas celle de l'utilisateur de l'app.
  return "fr";
}

// Langue courante accessible hors composants React (ex. libellés des boîtes de dialogue système).
let currentLang: Lang = detectLang();

function format(template: string, vars?: Record<string, string | number>): string {
  return vars ? template.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? `{${k}}`)) : template;
}

/** Traduction hors React. Dans un composant, préférer `useI18n().t` qui déclenche le rendu au changement de langue. */
export function tr(key: Key, vars?: Record<string, string | number>): string {
  return format(dictionaries[currentLang][key] ?? fr[key] ?? key, vars);
}

type I18nValue = { lang: Lang; setLang: (l: Lang) => void; t: (key: Key, vars?: Record<string, string | number>) => string };
const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(currentLang);

  const setLang = useCallback((l: Lang) => {
    currentLang = l;
    setLangState(l);
    try { localStorage.setItem(STORAGE_KEY, l); } catch { /* non bloquant */ }
  }, []);

  useEffect(() => { document.documentElement.lang = lang; }, [lang]);

  const value = useMemo<I18nValue>(() => ({ lang, setLang, t: (key, vars) => format(dictionaries[lang][key] ?? fr[key] ?? key, vars) }), [lang, setLang]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nValue {
  const ctx = useContext(I18nContext);
  if (!ctx) throw new Error("useI18n doit être utilisé dans <I18nProvider>");
  return ctx;
}
